  "varanasi/ramnagar": ["Ramnagar Fort", "The palace of the Maharaja of Benares on the far bank, and its vintage cars."],
  "katmandou/durbar": ["Durbar Square", "The pagoda temples of the old royal palace, and the window of the Kumari, the living goddess."],
  "katmandou/swayambhunath": ["Swayambhunath, the Monkey Temple", "Three hundred and sixty-five steps, the Buddha’s eyes painted on the stupa, and monkeys everywhere."],
