  "udaipur/bagore": ["Dance at Bagore ki Haveli", "Rajasthani dances in the courtyard of an 18th-century mansion by the water."],
  "udaipur/mousson": ["The Monsoon Palace", "A white palace on a hilltop, overlooking the lakes and the Aravalli hills."],
  "udaipur/kumbhalgarh": ["Kumbhalgarh Fort", "Thirty-six kilometers of ramparts running along the ridges, listed by UNESCO."],
  "leh-ladakh/shanti-stupa": ["Shanti Stupa at sunset", "A white stupa above Leh, and the Indus Valley reddened by evening."],
