  "venise/rialto": ["The Rialto Market in the early morning", "A fish market since 1097, open at 7 a.m., closed on Sundays and Mondays."],
  "naples/pompei": ["Pompeii", "Sixty-six hectares frozen in AD 79, and houses with their frescoes still on the walls."],
  "naples/vesuve": ["The crater of Vesuvius", "A thirty-minute climb over the lava, and the whole bay from the crater rim."],
  "naples/napoli-sotterranea": ["Underground Naples", "Forty meters beneath the city: Greek cisterns, 1943 air-raid shelters, and candlelit passages."],
  "naples/pizza": ["Neapolitan pizza, in Naples", "Sixty seconds at 450 degrees, two toppings allowed, and nothing else."],
  "naples/archeo-naples": ["The Archaeological Museum", "Everything taken out of Pompeii and Herculaneum, including the Secret Cabinet."],
  "naples/spaccanapoli": ["Spaccanapoli on foot", "The straight street that has split the old town in two since the Greeks, and everything spilling onto it."],
  "milan/cene": ["Leonardo’s Last Supper", "Fifteen minutes per slot, twenty-five people, and booking two months ahead."],
  "milan/duomo-milan": ["The Duomo terraces", "Three thousand four hundred statues, a hundred and thirty-five spires, and a walk on the roof."],
  "milan/brera": ["The Pinacoteca di Brera", "Mantegna, Raphael, Piero della Francesca, in a 17th-century palace above the fine arts academy."],
  "milan/navigli": ["Aperitivo on the Navigli", "The canals designed by Leonardo, and the Milanese aperitivo: one drink, buffet included."],
  "cinque-terre/sentier-azur": ["The Sentiero Azzurro", "Twelve kilometers from Monterosso to Riomaggiore, high above the sea, through the five villages."],
  "cinque-terre/vernazza": ["The harbor of Vernazza", "The only natural harbor of the five, its stacked houses, and the castle terrace above."],
  "cinque-terre/manarola": ["Manarola at dusk", "The Nessun Dorma viewpoint, and the ocher facades lighting up all at once."],
  "cinque-terre/bateau": ["The five villages from the sea", "The only way to understand how they cling to the cliff."],
  "amalfi/sentier-dieux": ["The Path of the Gods", "Seven kilometers from Bomerano to Nocelle, five hundred meters above the sea, downhill."],
  "amalfi/positano": ["Positano", "A village tumbling down the cliff to the beach, and a thousand steps to climb back up."],
  "amalfi/ravello": ["The gardens of Ravello", "Villa Rufolo and Villa Cimbrone, and the Terrace of Infinity 350 meters above the gulf."],
  "amalfi/duomo-amalfi": ["Amalfi Cathedral", "Sixty-two steps, an Arab-Norman facade, and a Cloister of Paradise with interlaced arches."],
  "amalfi/capri": ["A day trip to Capri", "The Blue Grotto if the sea allows, the Faraglioni, and the chairlift up Monte Solaro."],
  "palerme/chapelle-palatine": ["The Palatine Chapel", "Golden Byzantine mosaics beneath a wooden ceiling carved by Arab craftsmen."],
  "palerme/monreale": ["Monreale Cathedral", "Up in the hills, six thousand square meters of mosaics, and a cloister with twisted columns."],
  "palerme/ballaro": ["Ballarò market and its street food", "Arancine, pani ca’ meusa, panelle: the stallholders shout, you eat standing up."],
  "palerme/capucins": ["The Capuchin Catacombs", "Eight thousand mummified, clothed bodies lined up along the corridors: striking, best avoided if you’re sensitive."],
  "palerme/mondello": ["Mondello beach", "A bay of white sand and turquoise water, twenty minutes by bus from the center."],
  "palerme/massimo": ["An opera at the Teatro Massimo", "Italy’s largest opera house, and the staircase from The Godfather Part III."],
  "turin/egyptien": ["The Egyptian Museum", "The richest Egyptian collection outside Cairo, and the intact tomb of Kha and Merit."],
  "turin/mole": ["The Mole Antonelliana and the Cinema Museum", "A glass elevator inside the dome, and cinema told from the magic lantern to Fellini."],
  "turin/bicerin": ["A bicerin at Caffè Al Bicerin", "Coffee, chocolate and cream in three layers you don’t stir, in a café from 1763."],
  "turin/aperitivo": ["The Turin aperitivo", "Turin invented vermouth: one drink, and the buffet comes with it."],
  "turin/superga": ["The Basilica of Superga by rack railway", "A century-old rack railway, and the Alps in an arc from the hilltop."],
  "turin/venaria": ["La Venaria Reale", "The Versailles of the House of Savoy: the Gallery of Diana and restored gardens as far as the eye can see."],
  "bologne/piazza-maggiore": ["Piazza Maggiore and San Petronio", "The square of Neptune, and a basilica left unfinished, its facade half bare."],
  "bologne/san-luca": ["The San Luca portico", "Six hundred and sixty-six arches climbing four kilometers to the sanctuary."],
  "bologne/quadrilatero": ["The Quadrilatero and its delis", "Mortadella, Parmesan, fresh tortellini: the market lanes behind the piazza."],
  "bologne/archiginnasio": ["The Archiginnasio and its anatomical theater", "The old university, its thousands of coats of arms, and the wooden amphitheater where dissections took place."],
  "bologne/cours-pates": ["A fresh pasta class", "Rolling out the sfoglia with a pin, folding tortellini, and eating them at lunch."],
  "bologne/modene": ["Modena and balsamic vinegar", "Twenty minutes by train, a Romanesque cathedral, and a vinegar loft where it ages for twenty-five years."],
  "verone/arenes": ["The Verona Arena", "A Roman amphitheater with twenty-two thousand seats, still in use."],
  "verone/opera-arenes": ["An opera in the Arena", "In summer, Aida or Carmen under the stars, with candles lit on the stone steps."],
  "verone/juliette": ["Juliet’s House", "Italy’s most photographed balcony, in a courtyard covered in love notes."],
  "verone/castelvecchio": ["Castelvecchio and its bridge", "A Scaliger fortress turned into a museum by Carlo Scarpa, and a crenellated bridge over the Adige."],
  "verone/sirmione": ["Sirmione and Lake Garda", "A castle on the water, the Grottoes of Catullus, and a swim beneath the olive trees."],
  "verone/valpolicella": ["A tasting in Valpolicella", "Amarone, a wine made from grapes dried for three months, tasted at the winemaker’s."],
  "sienne/campo": ["Piazza del Campo", "A shell-shaped square sloping down to the Palazzo Pubblico, where people sit on the ground."],
  "sienne/duomo": ["The Duomo and its floor", "White and green marble, and an inlaid marble floor uncovered only a few weeks a year."],
  "sienne/torre-mangia": ["The Torre del Mangia", "Four hundred steps, and Tuscany laid out like a checkerboard to the horizon."],
  "sienne/san-gimignano": ["San Gimignano and its towers", "Fourteen medieval towers on a hill, and award-winning gelato on Piazza della Cisterna."],
  "sienne/chianti": ["A tasting in Chianti", "White roads between the cypresses, and black-rooster Chianti Classico tasted in the cellar."],
  "sienne/val-orcia": ["Pienza and the Val d’Orcia", "Bare hills and rows of cypresses, and Pienza pecorino."],
  "pise/tour": ["The Leaning Tower and the Field of Miracles", "Nearly three hundred steps in a tower leaning almost four degrees, then the baptistery and the cathedral."],
  "pise/lucques": ["Lucca and its walls by bike", "Four kilometers of tree-lined ramparts to ride around, encircling a town that has stayed whole."],
  "pise/quais": ["The Arno embankments and Borgo Stretto", "The arcades of the shopping street, then an aperitivo on the riverbank as the palaces are reflected in the Arno."],
  "pise/cavalieri": ["Piazza dei Cavalieri", "Vasari’s square and its palace with engraved facades, home of the Scuola Normale Superiore of Pisa."],
  "pise/san-rossore": ["San Rossore Park", "Pine woods, dunes and deer between Pisa and the sea, to explore on horseback or by bike."],
  "pise/tuttomondo": ["Keith Haring’s Tuttomondo mural", "One of the artist’s last murals, on the wall of a convent behind the station."],
  "genes/aquarium": ["The Genoa Aquarium", "One of the largest aquariums in Europe, in the old port redesigned by Renzo Piano."],
  "genes/via-garibaldi": ["Via Garibaldi and the Palazzi dei Rolli", "A street of Renaissance palaces listed by UNESCO, with the Palazzo Rosso and Palazzo Bianco museums."],
